using System.Numerics;using ToneCustoms.ShellStudio.Core;using ToneCustoms.ShellStudio.Export;using ToneCustoms.ShellStudio.Validation;using Xunit;
namespace ToneCustoms.ShellStudio.Tests;
public class CoreTests { [Fact]public void GridSnapWorks(){var g=new GeometryService();Assert.Equal(new Vector3(1,.5f,0),g.Snap(new(1.12f,.61f,.1f),.25f));}[Fact]public void WallHasExpectedType(){Assert.Equal(SceneObjectType.Wall,new GeometryService().Wall(Vector3.Zero).Type);}[Fact]public void EmptyProjectWarns(){Assert.Contains(new ProjectValidator().Validate(new()),x=>x.Area=="Geometry");}[Fact]public void BuilderCreatesManifest(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());var p=new ShellProject{Name="test_shell"};var r=new FiveMResourceBuilder().Prepare(p,root);Assert.True(File.Exists(Path.Combine(r,"fxmanifest.lua")));Directory.Delete(root,true);} }
